package com.enterpriseflow.entity;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="task_comments") public class TaskComment {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private Task task; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private User author; @Column(nullable=false,columnDefinition="TEXT") private String content; private Instant createdAt; protected TaskComment(){} public TaskComment(Task t,User a,String c){task=t;author=a;content=c;} @PrePersist void on(){createdAt=Instant.now();} public UUID getId(){return id;} public User getAuthor(){return author;} public String getContent(){return content;} public Instant getCreatedAt(){return createdAt;}}
